const uiThemeEvidenceRows=(config:LegacyRecord={})=>{
  const p=uiThemePreviewTokens(config)
  const evidence=p.evidence||{}
  const definitions=[
    ['menu.normal','메뉴 기본'],['menu.hover','메뉴 Hover'],['menu.active','메뉴 Active'],['submenu.normal','하위 메뉴 Open'],['user_menu.normal','사용자 메뉴 Open'],['button.hover','버튼 Hover'],['input.focus','입력 Focus'],['card.hover','Card Hover']
  ]
  return definitions.map(([key,label]: LegacyValue)=>{
    const item=evidence[key]||{}
    const status=item.status||'inferred'
    const source=item.source||((config?.theme==='custom')?'TOKEN_INFERRED':'SYSTEM_THEME')
    const confidence=Number(item.confidence||(status==='confirmed'?0.92:status==='reference'?0.78:0.45))
    return {key,label,status,source,confidence,selector:item.selector||'',fileName:item.file_name||'',referenceRole:item.reference_role||''}
  })
}
const uiThemeSourceNavigation=(config:LegacyRecord={})=>{
  const layout=config?.theme_layout_rules||{}
  const contract=layout?.layoutContract||layout?.layout_contract||{}
  const navigation=contract?.navigation||{}
  const labels=Array.isArray(navigation?.items)?navigation.items:(Array.isArray(layout?.sourceNavigationItems)?layout.sourceNavigationItems:[])
  const details=Array.isArray(navigation?.item_details)?navigation.item_details:(Array.isArray(layout?.sourceNavigationItemDetails)?layout.sourceNavigationItemDetails:[])
  const presentation=navigation?.presentation||layout?.sourceNavigationPresentation||{}
  const items=labels.map((label: LegacyValue,index: LegacyValue)=>({label:String(label||'').trim(),...(details[index]||{})})).filter((item: LegacyValue)=>item.label).slice(0,10)
  return {items,presentation,useSourceItems:navigation?.use_source_items_in_preview!==false}
}
const uiThemeMenuGlyph=(label: LegacyValue='',index: LegacyValue=0)=>{
  const value=String(label||'').toLowerCase()
  if(/home|홈/.test(value)) return '⌂'
  if(/issue|문제/.test(value)) return '◉'
  if(/pull|request|요청/.test(value)) return '⇄'
  if(/repo|저장소/.test(value)) return '▣'
  if(/project|프로젝트/.test(value)) return '▦'
  if(/discussion|대화|토론/.test(value)) return '◌'
  if(/code|코드/.test(value)) return '⌘'
  if(/market|상품|catalog/.test(value)) return '◇'
  if(/order|주문/.test(value)) return '▤'
  if(/report|리포트/.test(value)) return '▥'
  return ['◆','○','□','◇','△','◎'][index%6]
}
const uiThemePreviewPageModel=(label: LegacyValue='',index: LegacyValue=0)=>{
  const title=String(label||'Dashboard').trim()||'Dashboard'
  const key=title.toLowerCase()
  if(/dashboard|home|홈/.test(key)) return {kind:'dashboard',title,description:'선택한 메뉴의 Dashboard/Home 화면입니다.',kpis:[['Users','1,248'],['Orders','326'],['Status','Active']],placeholder:'검색어를 입력하세요'}
  if(/activity|issue|pull|discussion|활동|문제|요청|토론/.test(key)) return {kind:'activity',title,description:'최근 활동과 상태 변화가 표시되는 화면입니다.',kpis:[['Events','48'],['Open','12'],['Today','9']],rows:['새 작업이 등록되었습니다.','검토 상태가 업데이트되었습니다.','사용자 활동 기록이 추가되었습니다.']}
  if(/setting|설정/.test(key)) return {kind:'settings',title,description:'환경과 사용자 옵션을 변경하는 설정 화면입니다.',kpis:[['Profile','Ready'],['Alerts','On'],['Theme','Auto']],rows:['프로필 및 계정','알림 및 자동화','화면 및 테마']}
  if(/repo|project|catalog|product|order|market|저장소|프로젝트|상품|주문/.test(key)) return {kind:'collection',title,description:'목록·검색·상태를 확인하는 컬렉션 화면입니다.',kpis:[['Items',String(24+index*7)],['Updated','Today'],['Status','Ready']],placeholder:`${title} 검색`}
  return {kind:'generic',title,description:'선택한 메뉴에 맞춰 페이지가 전환됩니다.',kpis:[['Overview','12'],['Updates','5'],['Status','Ready']],placeholder:`${title} 검색`}
}
function UILayoutThemePreview({config={},compact=false,viewport='desktop'}:{config?:LegacyRecord;compact?:boolean;viewport?:string}){
  const [activeMenu,setActiveMenu]=useState('dashboard')
  const [activePage,setActivePage]=useState(0)
  const [submenuOpen,setSubmenuOpen]=useState(false)
  const [userMenuOpen,setUserMenuOpen]=useState(false)
  const [mobileMenuOpen,setMobileMenuOpen]=useState(false)
  const preview=uiThemePreviewTokens(config)
  const template=uiLayoutTemplateById(config?.template_id) as LegacyRecord
  const merged={...template,...config}
  const hasSidebar=Boolean(merged.sidebar)
  const hasHeader=Boolean(merged.header)
  const hasFooter=Boolean(merged.footer)
  const sidebarMenuIcons=Boolean(merged.sidebar_menu_icons)
  const headerIcons=Boolean(hasHeader&&merged.header_icons)
  const isMobile=viewport==='mobile'
  const showHeader=hasHeader||(isMobile&&hasSidebar)
  const vars=uiThemePreviewStyleVars(config)
  const label=config?.theme==='custom'?(config?.theme_name||'Custom Theme'):(config?.theme==='dark'?'Dark':config?.theme==='auto'?'Auto':'Light')
  const sourceNavigation=uiThemeSourceNavigation(config)
  const sourceMenuItems=(config?.theme==='custom'&&sourceNavigation.useSourceItems&&sourceNavigation.items.length>=2)?sourceNavigation.items:[]
  const iconTextMenu=String(sourceNavigation?.presentation?.mode||'').toLowerCase()==='icon_text'
    ||sourceMenuItems.filter((item: LegacyValue)=>item?.has_icon||item?.icon?.detected).length>=Math.max(2,Math.ceil(sourceMenuItems.length*.35))
  const previewPageItems=sourceMenuItems.length?sourceMenuItems.slice(0,5):[{label:'Dashboard'},{label:'Activity'},{label:'Settings'}]
  const previewPageSignature=previewPageItems.map((item: LegacyValue)=>String(item?.label||item||'')).join('|')
  const selectedPageIndex=Math.min(activePage,Math.max(0,previewPageItems.length-1))
  const selectedPageItem=previewPageItems[selectedPageIndex]||{label:'Dashboard'}
  const pageModel=uiThemePreviewPageModel(selectedPageItem?.label||selectedPageItem,selectedPageIndex)
  const renderMenuLabel=(item: LegacyValue,index: LegacyValue,forceIcon: LegacyValue=false)=>{
    const labelText=String(item?.label||item||'')
    const hasIcon=Boolean(forceIcon)||iconTextMenu||Boolean(item?.has_icon||item?.icon?.detected)
    return <span className={`ui-theme-preview-menu-label ${hasIcon?'with-icon':''}`}>{hasIcon&&<span className="ui-theme-preview-menu-icon" aria-hidden="true">{uiThemeMenuGlyph(labelText,index)}</span>}<em>{labelText}</em></span>
  }
  const menuClick=(id: LegacyValue,hasSubmenu: LegacyValue=false)=>{setActiveMenu(id);if(hasSubmenu)setSubmenuOpen((value: LegacyValue)=>!value);else setSubmenuOpen(false)}
  const evidenceRows=uiThemeEvidenceRows(config)
  const reproduction=Math.round(evidenceRows.reduce((sum: LegacyValue,row: LegacyValue)=>sum+row.confidence,0)/Math.max(1,evidenceRows.length)*100)
  useEffect(()=>{
    setSubmenuOpen(false)
    setUserMenuOpen(false)
    setMobileMenuOpen(false)
  },[viewport])
  useEffect(()=>{
    setActivePage(0)
  },[previewPageSignature])
  const mobileItem=(id: LegacyValue,item: LegacyValue,index: LegacyValue=0,hasSubmenu: LegacyValue=false,children:LegacyValue[]=[])=><div className="ui-theme-preview-mobile-menu-item" key={id}>
    <button className={activeMenu===id?'active':''} onClick={()=>menuClick(id,hasSubmenu)}>{renderMenuLabel(item,index,sidebarMenuIcons||headerIcons)}{hasSubmenu?<span>{submenuOpen&&activeMenu===id?'⌃':'⌄'}</span>:null}</button>
    {hasSubmenu&&submenuOpen&&activeMenu===id&&<div className="ui-theme-preview-mobile-submenu">{children.map((child: LegacyValue)=><button key={child}>{child}</button>)}</div>}
  </div>
  return <div className={`ui-theme-preview ${compact?'compact':''} ${viewport}`} style={vars}>
    <div className="ui-theme-preview-browser">
      {showHeader&&<header><b>{label}</b>{isMobile?<button type="button" className={`ui-theme-preview-mobile-menu-trigger ${mobileMenuOpen?'open':''}`} aria-label="모바일 메뉴 열기" aria-expanded={mobileMenuOpen} onClick={()=>{setMobileMenuOpen((value: LegacyValue)=>!value);setSubmenuOpen(false)}}><span>☰</span><em>{mobileMenuOpen?'닫기':'메뉴'}</em></button>:<nav>
        {(sourceMenuItems.length?sourceMenuItems.slice(0,3):[{label:'Home'},{label:'Products'},{label:'Reports'}]).map((item: LegacyValue,index: LegacyValue)=>{const id=`source-top-${index}`;return <button key={id} className={activeMenu===id?'active':''} onClick={()=>menuClick(id)}>{renderMenuLabel(item,index,headerIcons)}</button>})}
      </nav>}<div className="ui-theme-preview-header-end">{headerIcons&&<div className="ui-theme-preview-header-icons" aria-label="Header 아이콘 미리보기"><button type="button" title="검색" aria-label="검색">⌕</button><button type="button" title="알림" aria-label="알림">◉</button></div>}<div className="ui-theme-preview-user-wrap"><button className="ui-theme-preview-user-trigger" aria-label="사용자 메뉴" onClick={()=>{setUserMenuOpen((value: LegacyValue)=>!value);if(isMobile)setMobileMenuOpen(false)}}><i></i><span>Admin</span></button>{userMenuOpen&&<div className="ui-theme-preview-user-menu"><strong>사용자 메뉴</strong><button>프로필</button><button>설정</button><hr/><button>로그아웃</button></div>}</div></div></header>}
      {isMobile&&mobileMenuOpen&&<div className="ui-theme-preview-mobile-menu-layer">
        <button type="button" className="ui-theme-preview-mobile-menu-backdrop" aria-label="모바일 메뉴 닫기" onClick={()=>setMobileMenuOpen(false)}></button>
        <div className="ui-theme-preview-mobile-menu-panel">
          <div className="ui-theme-preview-mobile-menu-head"><strong>MENU</strong><button type="button" onClick={()=>setMobileMenuOpen(false)}>×</button></div>
          <div className="ui-theme-preview-mobile-menu-list">
            {sourceMenuItems.length
              ? sourceMenuItems.slice(0,8).map((item: LegacyValue,index: LegacyValue)=>mobileItem(`source-mobile-${index}`,item,index))
              : <>
                {hasHeader&&mobileItem('home',{label:'Home'},0)}
                {hasHeader&&mobileItem('products',{label:'Products'},1,true,['상품 조회','카테고리','재고 관리'])}
                {hasHeader&&mobileItem('reports',{label:'Reports'},2)}
                {hasSidebar&&mobileItem('dashboard',{label:'Dashboard'},3)}
                {hasSidebar&&mobileItem('catalog',{label:'Catalog'},4,true,['상품','카테고리'])}
                {hasSidebar&&mobileItem('orders',{label:'Orders'},5)}
              </>}
          </div>
        </div>
      </div>}
      <div className="ui-theme-preview-body">
        {hasSidebar&&<aside><strong>MENU</strong>
          {(sourceMenuItems.length?sourceMenuItems.slice(0,6):[{label:'Dashboard'},{label:'Catalog'},{label:'Orders'}]).map((item: LegacyValue,index: LegacyValue)=>{const id=`source-side-${index}`;return <button key={id} className={activeMenu===id?'active':''} onClick={()=>menuClick(id)}>{renderMenuLabel(item,index,sidebarMenuIcons)}</button>})}
        </aside>}
        <main>
          <div className={`ui-theme-preview-tabs ${config?.theme==='custom'?'imported-navigation':''}`}>
            {previewPageItems.map((item: LegacyValue,index: LegacyValue)=><button key={`${String(item?.label||item)}-${index}`} className={selectedPageIndex===index?'active':''} onClick={()=>setActivePage(index)}>{sourceMenuItems.length?renderMenuLabel(item,index):String(item?.label||item)}</button>)}
          </div>
          <div key={`${pageModel.kind}-${pageModel.title}`} className={`ui-theme-preview-page ui-theme-preview-page-${pageModel.kind}`}>
            <div className="ui-theme-preview-title"><div><b>{pageModel.title}</b><small>{pageModel.description} · 메뉴 클릭과 Hover로 가져온 상태/동작 스타일을 확인하세요.</small></div><button className="ui-theme-preview-primary">Primary</button></div>
            <div className="ui-theme-preview-kpis">{pageModel.kpis.map(([name,value]: LegacyValue)=><article key={name}><small>{name}</small><b>{value}</b></article>)}</div>
            {pageModel.kind==='activity'?<section className="ui-theme-preview-card ui-theme-preview-activity">{(pageModel.rows||[]).map((row: LegacyValue,index: LegacyValue)=><div key={row}><span>{index+1}</span><p>{row}</p><small>{index===0?'방금 전':`${index*7+3}분 전`}</small></div>)}</section>
              :pageModel.kind==='settings'?<section className="ui-theme-preview-card ui-theme-preview-settings">{(pageModel.rows||[]).map((row: LegacyValue,index: LegacyValue)=><label key={row}><span><b>{row}</b><small>{index===0?'계정 기본값을 관리합니다.':index===1?'알림과 자동 실행을 설정합니다.':'가져온 Theme 동작을 확인합니다.'}</small></span><input type="checkbox" defaultChecked={index!==1}/></label>)}</section>
              :<section className="ui-theme-preview-card"><div className="ui-theme-preview-form"><input placeholder={pageModel.placeholder||'클릭하여 Focus 스타일 확인'}/><button>검색</button></div><div className="ui-theme-preview-table"><i></i><i></i><i></i></div></section>}
          </div>
        </main>
      </div>
      {hasFooter&&<footer><span></span><span></span><span></span></footer>}
    </div>
    {!compact&&<div className="ui-theme-preview-verification">
      <div className="ui-theme-preview-verification-head"><div><strong>외부 스타일 재현 근거</strong><small>색상 샘플이 아니라 실제 URL CSS Selector 또는 상태별 캡처 참고 여부를 표시합니다.</small></div><b>{config?.theme==='custom'?`${reproduction}%`:'기본'}</b></div>
      <div className="ui-theme-preview-evidence-grid">{evidenceRows.map((row: LegacyValue)=><div key={row.key} className={`evidence ${row.status}`}><span>{row.label}</span><b>{row.status==='confirmed'?'URL CSS 확인':row.status==='reference'?'캡처 참고':'추정/기본값'}</b><small>{row.selector?row.selector:row.fileName?`${row.fileName}${row.referenceRole?` · ${row.referenceRole}`:''}`:row.source}</small></div>)}</div>
      {config?.theme==='custom'&&<div className="ui-theme-preview-source-note"><span>URL CSS 확인 항목은 실제 Selector 상태 규칙을 사용합니다.</span><span>캡처 참고 항목은 사용자가 지정한 상태 이미지에서 보완합니다.</span><span>근거가 없는 상태는 임의 복제라고 표시하지 않고 추정/기본값으로 구분합니다.</span></div>}
    </div>}
  </div>
}

const uiLayoutSummary=(value: LegacyValue)=>{
  if(!value?.template_id) return ''
  const template=uiLayoutTemplateById(value.template_id)
  if(value?.enabled===false||value?.template_id==='headless_agent') return 'UI 없음 · Headless Agent · Agent Runtime 유지'
  const nav=({header_sidebar:'상단+좌측 메뉴',left:'좌측 메뉴',top:'상단 메뉴',none:'메뉴 없음'} as LegacyRecord)[value.navigation]||value.navigation||''
  const themeLabel=value.theme==='custom'?(value.theme_name||'Custom Theme'):(value.theme==='dark'?'Dark':value.theme==='auto'?'Auto':'Light')
  const parts=[template.name||value.template_id,nav,value.sidebar&&value.sidebar_menu_icons?'좌측 메뉴 아이콘':'',value.header&&value.header_icons?'Header 아이콘':'',value.footer?'Footer':'',value.user_menu?'사용자 메뉴':'',themeLabel,value.agent_runtime_persistent!==false?'Agent 실행 유지':''].filter(Boolean)
  return parts.join(' · ')
}

function UILayoutWireframe({config={},compact=false}:{config?:LegacyRecord;compact?:boolean}){
  const template=uiLayoutTemplateById(config.template_id) as LegacyRecord
  const merged={...template,...config}
  const components=Array.isArray(merged.components)?merged.components:[]
  const hasSidebar=Boolean(merged.sidebar)
  const hasHeader=Boolean(merged.header)
  const hasFooter=Boolean(merged.footer)
  const userMenu=Boolean(merged.user_menu)
  const sidebarMenuIcons=Boolean(merged.sidebar_menu_icons)
  const headerIcons=Boolean(hasHeader&&merged.header_icons)
  const layout=merged.main_layout||'one_column'
  const cards=Math.min(compact?4:6,Math.max(3,components.length||4))
  const customTheme=merged.theme==='custom'
  return <div style={uiThemeWireframeStyle(merged)} className={`ui-layout-wireframe ${customTheme?'custom':uiThemeIsDark(merged)?'dark':'light'} ${compact?'compact':''}`}>
    {hasHeader&&<div className="ui-layout-wf-header"><i></i><div className={`ui-layout-wf-nav ${headerIcons?'with-icons':''}`}><span></span><span></span><span></span></div><div className="ui-layout-wf-header-end">{headerIcons&&<span className="ui-layout-wf-header-actions"><i></i><i></i></span>}{userMenu&&<b></b>}</div></div>}
    <div className="ui-layout-wf-body">
      {hasSidebar&&<div className={`ui-layout-wf-sidebar ${sidebarMenuIcons?'with-icons':''}`}><i></i><i></i><i></i><i></i><i></i></div>}
      <div className={`ui-layout-wf-main ${layout}`}>
        <div className="ui-layout-wf-search"></div>
        <div className="ui-layout-wf-kpis"><span></span><span></span><span></span></div>
        <div className="ui-layout-wf-content">
          {Array.from({length:cards}).map((_: LegacyValue,index: LegacyValue)=><span key={index}></span>)}
        </div>
      </div>
      {layout==='three_column'&&<div className="ui-layout-wf-context"><span></span><span></span><span></span></div>}
    </div>
    {hasFooter&&<div className="ui-layout-wf-footer"><span></span><span></span><span></span></div>}
  </div>
}

function UILayoutTemplateGallery({open,value,onClose,onApply,purposeText=''}:LegacyRecord){
  const currentTemplate=uiLayoutTemplateById(value?.template_id)
  const [selectedId,setSelectedId]=useState(value?.template_id||currentTemplate.id)
  const [category,setCategory]=useState('추천')
  const [draft,setDraft]=useState(()=>normalizeUILayoutConfig(currentTemplate,{...value,template_id:value?.template_id||currentTemplate.id}))
  const [customThemes,setCustomThemes]=useState<LegacyValue[]>([])
  const [frontendThemeTargets,setFrontendThemeTargets]=useState<LegacyValue[]>([])
  const [frontendThemeListOpen,setFrontendThemeListOpen]=useState(false)
  const [themeImportOpen,setThemeImportOpen]=useState(false)
  const [themeImportName,setThemeImportName]=useState('')
  const [themeImportUrl,setThemeImportUrl]=useState('')
  const [themeImportFiles,setThemeImportFiles]=useState<(File|null)[]>([null,null,null])
  const [themeImportRoles,setThemeImportRoles]=useState(['default','menu_hover','user_menu_open'])
  const [themeImportAnalyses,setThemeImportAnalyses]=useState<LegacyValue[]>([])
  const [themeImportPreview,setThemeImportPreview]=useState<LegacyValue|null>(null)
  const [themeImportBusy,setThemeImportBusy]=useState(false)
  const [themeImportError,setThemeImportError]=useState('')
  const [themeBackendWarning,setThemeBackendWarning]=useState('')
  const [themePreviewOpen,setThemePreviewOpen]=useState(false)
  const [themePreviewViewport,setThemePreviewViewport]=useState('desktop')
  useEffect(()=>{
    if(!open) return
    const template=uiLayoutTemplateById(value?.template_id)
    const next=normalizeUILayoutConfig(template,{...value,template_id:value?.template_id||template.id})
    setSelectedId(next.template_id)
    setDraft(next)
  },[open,value?.template_id])
  useEffect(()=>{
    if(!open) return
    let alive=true
    Promise.allSettled([api('/ui-themes'),api('/ui-themes/frontend-targets')]).then((results: LegacyValue)=>{
      if(!alive) return
      const themeResult=results[0]?.status==='fulfilled'?results[0].value:null
      const frontendResult=results[1]?.status==='fulfilled'?results[1].value:null
      setCustomThemes(Array.isArray(themeResult?.themes)?themeResult.themes:[])
      setFrontendThemeTargets(Array.isArray(frontendResult?.targets)?frontendResult.targets:[])
      const rejected=results.find((item: LegacyValue)=>item?.status==='rejected')
      setThemeBackendWarning(rejected?String(rejected.reason?.message||'Theme Backend API 연결을 확인할 수 없습니다.'):'')
    }).catch((error: LegacyValue)=>{if(alive){setCustomThemes([]);setFrontendThemeTargets([]);setThemeBackendWarning(String(asLegacyError(error).message||error))}})
    return()=>{alive=false}
  },[open])
  if(!open) return null
  const purpose=String(purposeText||'').toLowerCase()
  const scored=UI_LAYOUT_TEMPLATES.map((template: LegacyValue)=>({
    template,
    score:(template.keywords||[]).reduce((sum: LegacyValue,key: LegacyValue)=>sum+(purpose.includes(String(key).toLowerCase())?2:0),0)
      +(value?.app_type&&template.app_type===value.app_type?1:0)
  })).sort((a: LegacyValue,b: LegacyValue)=>b.score-a.score)
  const recommendedIds=new Set(scored.slice(0,5).map((item: LegacyValue)=>item.template.id))
  const categories=['추천','웹앱','대시보드','쇼핑/검색','AI/Chat','관리자','웹사이트','모바일','기타']
  const visible=UI_LAYOUT_TEMPLATES.filter((template: LegacyValue)=>category==='추천'?recommendedIds.has(template.id):template.category===category)
  const choose=(template: LegacyValue)=>{
    setSelectedId(template.id)
    setDraft(normalizeUILayoutConfig(template,{template_id:template.id}))
  }
  const patch=(next: LegacyValue)=>setDraft((prev: LegacyValue)=>({...prev,...next}))
  const selectThemeValue=(raw: LegacyValue)=>{
    const value=String(raw||'light')
    if(value.startsWith('custom:')){
      const themeId=Number(value.slice(7))
      const theme=customThemes.find((item: LegacyValue)=>Number(item.id)===themeId)
      if(theme) patch({theme:'custom',theme_id:theme.id,theme_name:theme.name,theme_tokens:theme.tokens||{},theme_component_rules:theme.component_rules||{},theme_layout_rules:theme.layout_rules||{},theme_source_type:theme.source_type||'',theme_source_url:theme.source_url||'',theme_source_label:theme.source_label||''})
      return
    }
    patch({theme:value,theme_id:null,theme_name:'',theme_tokens:{},theme_component_rules:{},theme_layout_rules:{},theme_source_type:'',theme_source_url:'',theme_source_label:''})
  }
  const mergeThemeImageAnalyses=(analyses:LegacyValue[]=[])=>{
    const rows=(analyses||[]).filter(Boolean)
    if(!rows.length) return null
    const colorKeys=['primary','secondary','background','surface','textPrimary','textSecondary','border','success','danger']
    const chooseMostCommon=(values:LegacyValue[]=[])=>{
      const counts=new Map<LegacyValue,LegacyValue>()
      values.filter(Boolean).forEach((value: LegacyValue)=>counts.set(String(value),(counts.get(String(value))||0)+1))
      return [...counts.entries()].sort((a: LegacyValue,b: LegacyValue)=>b[1]-a[1])[0]?.[0]||''
    }
    const colors:LegacyRecord={}
    colorKeys.forEach((key: LegacyValue)=>{
      const value=chooseMostCommon(rows.map((row: LegacyValue)=>row?.tokens?.colors?.[key]))
      if(value) colors[key]=value
    })
    const numericMedian=(values:LegacyValue[]=[],fallback: LegacyValue)=>{
      const nums=values.map(Number).filter(Number.isFinite).sort((a: LegacyValue,b: LegacyValue)=>a-b)
      if(!nums.length) return fallback
      return nums[Math.floor(nums.length/2)]
    }
    const first=rows[0]||{}
    const tokens={
      colors:{...(first.tokens?.colors||{}),...colors},
      typography:{...(first.tokens?.typography||{})},
      radius:{
        button:numericMedian(rows.map((row: LegacyValue)=>row?.tokens?.radius?.button),first.tokens?.radius?.button??8),
        card:numericMedian(rows.map((row: LegacyValue)=>row?.tokens?.radius?.card),first.tokens?.radius?.card??12),
        input:numericMedian(rows.map((row: LegacyValue)=>row?.tokens?.radius?.input),first.tokens?.radius?.input??8),
      },
      shadow:{...(first.tokens?.shadow||{})},
      spacing:{...(first.tokens?.spacing||{})},
    }
    const rules:LegacyRecord=buildImageThemeRules(tokens)
    const menuNormal=chooseMostCommon(rows.map((row: LegacyValue)=>row?.component_rules?.menu?.normal?.background))
    const hoverCandidates=rows.flatMap((row: LegacyValue)=>[row?.component_rules?.menu?.hover?.background,row?.component_rules?.menu?.active?.background]).filter(Boolean)
    const menuHover=chooseMostCommon(hoverCandidates.filter((color: LegacyValue)=>color!==menuNormal))||chooseMostCommon(hoverCandidates)||colors.primary
    const menuNormalText=chooseMostCommon(rows.map((row: LegacyValue)=>row?.component_rules?.menu?.normal?.color))||tokens.colors?.textPrimary
    const menuHoverText=chooseMostCommon(rows.map((row: LegacyValue)=>row?.component_rules?.menu?.hover?.color))||'#ffffff'
    rules.component_rules.menu={
      ...(rules.component_rules.menu||{}),
      normal:{...(rules.component_rules.menu?.normal||{}),...(menuNormal?{background:menuNormal}:{}) ,...(menuNormalText?{color:menuNormalText}:{})},
      hover:{...(rules.component_rules.menu?.hover||{}),...(menuHover?{background:menuHover,border:menuHover}:{}) ,...(menuHoverText?{color:menuHoverText}:{})},
      active:{...(rules.component_rules.menu?.active||{}),...(menuHover?{background:menuHover,border:menuHover}:{}) ,...(menuHoverText?{color:menuHoverText}:{})},
      source:rows.length>1?'IMAGE_MULTI_REFERENCE':'IMAGE_MENU_REGION_INFERRED'
    }
    const preview=[...new Set(rows.flatMap((row: LegacyValue)=>row?.preview_colors||[]))].slice(0,8)
    return {tokens,preview_colors:preview,...rules}
  }
  const importTheme=async()=>{
    setThemeImportBusy(true); setThemeImportError('')
    try{
      const name=String(themeImportName||'').trim()
      if(!name) throw new Error('Theme 이름을 입력하세요.')
      const url=String(themeImportUrl||'').trim()
      const files=(Array.isArray(themeImportFiles)?themeImportFiles:[]).filter(Boolean)
      if(!url&&!files.length) throw new Error('웹사이트 URL 또는 화면 캡처 이미지를 하나 이상 입력하세요.')

      let analyses=Array.isArray(themeImportAnalyses)?themeImportAnalyses:[]
      const slots=Array.isArray(themeImportFiles)?themeImportFiles:[null,null,null]
      if(files.length&&(!Array.isArray(analyses)||analyses.length!==slots.length||slots.some((file: LegacyValue,index: LegacyValue)=>Boolean(file)&&!analyses[index]))){
        analyses=[]
        for(let index=0;index<slots.length;index++){
          const file=slots[index]
          analyses[index]=file?await extractThemeTokensFromImage(file,themeImportRoles?.[index]||'default'):null
        }
        setThemeImportAnalyses(analyses)
        setThemeImportPreview(mergeThemeImageAnalyses(analyses.filter(Boolean)))
      }
      const result=await api('/ui-themes/import',{method:'POST',body:JSON.stringify({
        name,
        url,
        images:(Array.isArray(themeImportFiles)?themeImportFiles:[]).map((file: LegacyValue,index: LegacyValue)=>file?({
          file_name:file.name,
          reference_role:themeImportRoles?.[index]||'default',
          tokens:analyses?.[index]?.tokens||{},
          component_rules:analyses?.[index]?.component_rules||{},
          layout_rules:analyses?.[index]?.layout_rules||{},
          preview_colors:analyses?.[index]?.preview_colors||[],
        }):null).filter(Boolean),
        scope:'GLOBAL'
      })})
      const theme=result?.theme
      if(!theme) throw new Error('Theme 저장 결과를 확인할 수 없습니다.')
      if(Array.isArray(result?.warnings)&&result.warnings.length){
        setThemeBackendWarning(`Theme 저장 완료 · 일부 참고 소스 제외: ${result.warnings.join(' / ')}`)
      }else{
        setThemeBackendWarning('')
      }
      setCustomThemes((prev: LegacyValue)=>[theme,...prev.filter((item: LegacyValue)=>Number(item.id)!==Number(theme.id))])
      patch({theme:'custom',theme_id:theme.id,theme_name:theme.name,theme_tokens:theme.tokens||{},theme_component_rules:theme.component_rules||{},theme_layout_rules:theme.layout_rules||{},theme_source_type:theme.source_type||'',theme_source_url:theme.source_url||'',theme_source_label:theme.source_label||''})
      setThemeImportOpen(false); setThemeImportName(''); setThemeImportUrl(''); setThemeImportFiles([null,null,null]); setThemeImportRoles(['default','menu_hover','user_menu_open']); setThemeImportAnalyses([]); setThemeImportPreview(null)
    }catch(error){setThemeImportError(String(asLegacyError(error).message||error))}finally{setThemeImportBusy(false)}
  }
  const analyzeThemeImageSlots=async(nextSlots: LegacyValue,nextRoles: LegacyValue=themeImportRoles)=>{
    const slots=Array.isArray(nextSlots)?nextSlots:[null,null,null]
    setThemeImportAnalyses([]); setThemeImportPreview(null)
    if(!slots.some(Boolean)) return
    const analyses:LegacyValue[]=[]
    for(let index=0;index<slots.length;index++){
      analyses[index]=slots[index]?await extractThemeTokensFromImage(slots[index],nextRoles?.[index]||'default'):null
    }
    setThemeImportAnalyses(analyses)
    setThemeImportPreview(mergeThemeImageAnalyses(analyses.filter(Boolean)))
  }
  const chooseThemeImageSlot=async(index: LegacyValue,fileList: LegacyValue)=>{
    setThemeImportError('')
    const file=(Array.from(fileList||[]).filter(Boolean) as File[])[0]||null
    if(file){
      if(!String(file.type||'').startsWith('image/')){setThemeImportError('이미지 파일만 선택할 수 있습니다.');return}
      if(file.size>25*1024*1024){setThemeImportError(`'${file.name}' 파일은 25MB를 초과합니다.`);return}
    }
    const next=[...(Array.isArray(themeImportFiles)?themeImportFiles:[null,null,null])]
    while(next.length<3) next.push(null)
    next[index]=file
    setThemeImportFiles(next.slice(0,3))
    try{await analyzeThemeImageSlots(next.slice(0,3))}catch(error){setThemeImportError(String(asLegacyError(error).message||error))}
  }
  const removeThemeImage=(index: LegacyValue)=>{
    const next=[...(Array.isArray(themeImportFiles)?themeImportFiles:[null,null,null])]
    while(next.length<3) next.push(null)
    next[index]=null
    setThemeImportFiles(next.slice(0,3))
    analyzeThemeImageSlots(next.slice(0,3)).catch((error: LegacyValue)=>setThemeImportError(String(asLegacyError(error).message||error)))
  }
  const changeThemeImageRole=(index: LegacyValue,role: LegacyValue)=>{
    const next=[...(Array.isArray(themeImportRoles)?themeImportRoles:['default','menu_hover','user_menu_open'])]
    while(next.length<3) next.push('default')
    next[index]=String(role||'default')
    setThemeImportRoles(next.slice(0,3))
    analyzeThemeImageSlots(themeImportFiles,next.slice(0,3)).catch((error: LegacyValue)=>setThemeImportError(String(asLegacyError(error).message||error)))
  }
  const deleteCustomTheme=async(theme: LegacyValue)=>{
    if(!theme?.id) return
    if(!window.confirm(`Theme '${theme.name}'을(를) 삭제하시겠습니까?`)) return
    try{
      await api(`/ui-themes/${theme.id}`,{method:'DELETE'})
      setCustomThemes((prev: LegacyValue)=>prev.filter((item: LegacyValue)=>Number(item.id)!==Number(theme.id)))
      if(Number(draft.theme_id)===Number(theme.id)) selectThemeValue('auto')
    }catch(error){setThemeImportError(String(asLegacyError(error).message||error))}
  }
  const selected=uiLayoutTemplateById(selectedId)
  return <div className="ui-layout-gallery-backdrop" role="dialog" aria-modal="true" aria-label="UI Layout Template Gallery">
    <div className="ui-layout-gallery-modal">
      <div className="ui-layout-gallery-head">
        <div><span>NEW AGENT · UI / LAYOUT</span><strong>레이아웃 템플릿 갤러리</strong><small>화면 구조와 함께 메뉴 이동 후 상태 복원, 실행 중 Agent 표시, 완료/실패 알림 정책을 설정합니다.</small></div>
        <button type="button" onClick={onClose}>×</button>
      </div>
      <div className="ui-layout-gallery-toolbar">
        {categories.map((item: LegacyValue)=><button key={item} type="button" className={category===item?'active':''} onClick={()=>setCategory(item)}>{item}</button>)}
      </div>
      <div className="ui-layout-gallery-body">
        <div className="ui-layout-gallery-grid">
          {visible.map((template: LegacyValue)=><button type="button" key={template.id} className={`ui-layout-template-card ${selectedId===template.id?'selected':''}`} onClick={()=>choose(template)}>
            <UILayoutWireframe config={{...template,template_id:template.id}} compact={true}/>
            <div><strong>{template.name}</strong><small>{template.description}</small></div>
            {recommendedIds.has(template.id)&&<span className="ui-layout-recommended">추천</span>}
          </button>)}
        </div>
        <aside className="ui-layout-config-panel">
          <div className="ui-layout-config-preview"><UILayoutWireframe config={draft}/></div>
          <div className="ui-layout-config-title"><strong>{selected.name}</strong><small>{selected.description}</small></div>

          <section className="ui-layout-config-section">
            <div className="ui-layout-config-section-head"><strong>UI 구성</strong><small>화면에 표시할 공통 영역</small></div>
            <div className="ui-layout-toggle-grid">
              <label><input type="checkbox" checked={Boolean(draft.header)} onChange={(e: LegacyValue)=>patch({header:e.target.checked,header_icons:e.target.checked?Boolean(draft.header_icons):false})}/>상단 Header</label>
              <label><input type="checkbox" checked={Boolean(draft.sidebar)} onChange={(e: LegacyValue)=>patch({sidebar:e.target.checked,sidebar_menu_icons:e.target.checked?Boolean(draft.sidebar_menu_icons):false,navigation:e.target.checked?(draft.header?'header_sidebar':'left'):(draft.header?'top':'none')})}/>좌측 메뉴</label>
              <label><input type="checkbox" checked={Boolean(draft.sidebar_menu_icons)} disabled={!draft.sidebar} onChange={(e: LegacyValue)=>patch({sidebar_menu_icons:e.target.checked})}/>좌측 메뉴 아이콘</label>
              <label><input type="checkbox" checked={Boolean(draft.header_icons)} disabled={!draft.header} onChange={(e: LegacyValue)=>patch({header_icons:e.target.checked})}/>상단 Header 아이콘</label>
              <label><input type="checkbox" checked={Boolean(draft.sidebar_collapsible)} disabled={!draft.sidebar} onChange={(e: LegacyValue)=>patch({sidebar_collapsible:e.target.checked})}/>Sidebar 접기</label>
              <label><input type="checkbox" checked={Boolean(draft.footer)} onChange={(e: LegacyValue)=>patch({footer:e.target.checked})}/>Footer</label>
              <label><input type="checkbox" checked={Boolean(draft.user_menu)} onChange={(e: LegacyValue)=>patch({user_menu:e.target.checked})}/>사용자 메뉴</label>
              <label><input type="checkbox" checked={draft.responsive!==false} onChange={(e: LegacyValue)=>patch({responsive:e.target.checked})}/>반응형</label>
            </div>
            <div className="ui-layout-icon-option-note"><span>아이콘 옵션</span><small>선택하면 미리보기와 생성 Agent의 Sidebar/Header에 의미에 맞는 표준 아이콘을 함께 적용합니다.</small></div>
          </section>

          <section className="ui-layout-config-section">
            <div className="ui-layout-config-section-head"><strong>레이아웃</strong><small>화면 배치와 Theme</small></div>
            <label className="ui-layout-select-field"><span>Main Layout</span><select value={draft.main_layout||'one_column'} onChange={(e: LegacyValue)=>patch({main_layout:e.target.value})}><option value="one_column">1 Column</option><option value="two_column">2 Column</option><option value="three_column">3 Column</option><option value="grid">Card Grid</option><option value="dashboard">Dashboard</option><option value="landing">Landing</option><option value="mobile">Mobile First</option></select></label>
            <div className="ui-layout-theme-field">
              <label className="ui-layout-select-field"><span>Theme</span><select value={uiThemeSelectValue(draft)} onChange={(e: LegacyValue)=>selectThemeValue(e.target.value)}><option value="light">Light</option><option value="dark">Dark</option><option value="auto">Auto</option>{customThemes.length>0&&<optgroup label="사용자 Theme">{customThemes.map((theme: LegacyValue)=><option key={theme.id} value={`custom:${theme.id}`}>{theme.name}</option>)}</optgroup>}</select></label>
              <button type="button" className="ui-layout-theme-import-button" onClick={()=>{setThemeImportOpen((value: LegacyValue)=>!value);setThemeImportError('')}}>+ 스타일 가져오기</button>
            </div>
            <div className="ui-layout-theme-target-summary">
              <div>
                <strong>Frontend Theme 적용</strong>
                <small>공통 Design Token을 선택한 Frontend/스타일 방식으로 자동 변환합니다.</small>
              </div>
              <div className="ui-layout-theme-target-actions">
                <span>{frontendThemeTargets.length||'–'} Adapters</span>
                <button type="button" onClick={()=>setFrontendThemeListOpen(true)}>지원 목록 보기</button>
              </div>
            </div>
            {themeBackendWarning&&<div className="ui-layout-theme-backend-warning"><b>Theme 알림</b><span>{themeBackendWarning}</span><small>SYSTEM_ADMIN에서 Backend까지 완전히 재시작하면 Frontend/Backend 버전 불일치도 함께 해소됩니다.</small></div>}
            {draft.theme==='custom'&&<div className="ui-layout-selected-theme">
              <div className="ui-layout-theme-palette">{(draft.theme_tokens?.colors?Object.values(draft.theme_tokens.colors).slice(0,5):[]).map((color: LegacyValue,index: LegacyValue)=><i key={`${color}-${index}`} style={{background:String(color)}}></i>)}</div>
              <div><strong>{draft.theme_name||'Custom Theme'}</strong><small>{draft.theme_source_type==='COMBINED'?'URL + 화면 캡처 통합 Theme':draft.theme_source_type==='URL'?'URL 분석 Theme':draft.theme_source_type==='IMAGE'?'화면 캡처 Theme':'사용자 Theme'} · 선택된 Frontend 기술의 native Theme 방식으로 자동 변환 적용</small></div>
              <button type="button" onClick={()=>deleteCustomTheme(customThemes.find((item: LegacyValue)=>Number(item.id)===Number(draft.theme_id)))}>삭제</button>
            </div>}
            <div className="ui-layout-theme-live-preview-card" style={uiThemePreviewStyleVars({...draft,template_id:selectedId})}>
              <div className="ui-layout-theme-live-preview-head">
                <div><strong>Theme 미리보기</strong><small>{draft.theme==='custom'?(draft.theme_name||'Custom Theme'):(draft.theme==='dark'?'Dark':draft.theme==='auto'?'Auto':'Light')} · {selected.name}</small></div>
                <button type="button" onClick={()=>{setThemePreviewViewport('desktop');setThemePreviewOpen(true)}}>전체 미리보기</button>
              </div>
              <UILayoutThemePreview config={{...draft,template_id:selectedId}} compact={true}/>
              <div className="ui-layout-theme-state-swatches">
                <span className="normal">메뉴 Normal</span><span className="hover">Hover</span><span className="active">Active</span>
              </div>
            </div>
            {themeImportOpen&&<div className="ui-layout-theme-import-panel unified-source">
              <div className="ui-layout-theme-import-source-head">
                <div><strong>스타일 참고 자료</strong><small>URL과 캡처 이미지를 함께 넣을 수 있습니다. 하나만 입력해도 되고, 둘 다 있으면 통합 분석합니다.</small></div>
                <span>{themeImportFiles.filter(Boolean).length}/3 이미지</span>
              </div>
              <label><span>Theme 이름</span><input value={themeImportName} onChange={(e: LegacyValue)=>setThemeImportName(e.target.value)} placeholder="예: 쇼핑몰 A 스타일"/></label>
              <label><span>웹사이트 URL</span><input value={themeImportUrl} onChange={(e: LegacyValue)=>setThemeImportUrl(e.target.value)} placeholder="선택 입력 · https://example.com"/></label>
              <div className="ui-layout-theme-file-slots">
                {[0,1,2].map((index: LegacyValue)=>{const file=themeImportFiles[index];return <div key={index} className={`ui-layout-theme-file-slot-wrap ${file?'filled':''}`}>
                  <label className={`ui-layout-theme-file-slot ${file?'filled':''}`}>
                    <span>화면 캡처 {index+1}</span>
                    <input type="file" accept="image/*" onChange={(e: LegacyValue)=>chooseThemeImageSlot(index,e.target.files)}/>
                    <b title={file?.name||''}>{file?file.name:'이미지 선택'}</b>
                    <small>{file?`${Math.max(1,Math.round(file.size/1024))} KB`:'선택 입력 · 최대 25MB'}</small>
                    {file&&<button type="button" onClick={(e: LegacyValue)=>{e.preventDefault();e.stopPropagation();removeThemeImage(index)}}>×</button>}
                  </label>
                  <label className="ui-layout-theme-reference-role"><span>참고 상태</span><select value={themeImportRoles[index]||'default'} onChange={(e: LegacyValue)=>changeThemeImageRole(index,e.target.value)}>
                    <option value="default">기본 화면</option><option value="menu_hover">메뉴 Hover</option><option value="menu_active">메뉴 Active</option><option value="submenu_open">하위 메뉴 Open</option><option value="user_menu_open">사용자 메뉴 Open</option><option value="button_hover">버튼 Hover</option><option value="input_focus">입력 Focus</option><option value="mobile">모바일 화면</option>
                  </select></label>
                </div>})}
              </div>
              {themeImportPreview&&<div className="ui-layout-theme-import-palette">{(themeImportPreview.preview_colors||[]).map((color: LegacyValue,index: LegacyValue)=><i key={`${color}-${index}`} style={{background:color}} title={color}></i>)}</div>}
              <div className="ui-layout-theme-menu-state-note">
                <b>메뉴 상태까지 분석</b>
                <span>URL CSS의 메뉴/Navigation 기본·Hover·Active, 하위 메뉴, 사용자 메뉴, Button/Input/Card 상태 규칙을 추출합니다. 캡처 이미지는 각 슬롯에서 기본/Hover/메뉴 Open 등 참고 상태를 지정해 URL 분석 결과를 보완합니다.</span>
              </div>
              <small className="ui-layout-theme-import-help">URL에서는 HTML/CSS의 색상·폰트·Radius·Shadow와 실제 :hover/:focus/.active/Dropdown/User Menu Selector를 분석하고, 이미지는 지정한 UI 상태의 실제 화면 특징을 참고합니다. URL과 이미지가 모두 있으면 URL의 CSS 상태 규칙과 이미지의 실제 화면 색감을 합쳐 하나의 Design Token Theme으로 저장합니다. 로고·문구·이미지·고유 콘텐츠는 복제하지 않습니다.</small>
              {customThemes.length>0&&<div className="ui-layout-theme-library"><strong>저장된 Theme</strong>{customThemes.slice(0,8).map((theme: LegacyValue)=><div key={theme.id}><span className="ui-layout-theme-library-palette">{(theme.preview_colors||[]).slice(0,4).map((color: LegacyValue,index: LegacyValue)=><i key={`${color}-${index}`} style={{background:color}}></i>)}</span><b>{theme.name}</b><em>{theme.source_type==='COMBINED'?'URL+이미지':theme.source_type==='URL'?'URL':theme.source_type==='IMAGE'?'이미지':'Custom'}</em><button type="button" onClick={()=>{selectThemeValue(`custom:${theme.id}`);setThemeImportOpen(false)}}>적용</button><button type="button" className="danger" onClick={()=>deleteCustomTheme(theme)}>삭제</button></div>)}</div>}
              {themeImportError&&<div className="ui-layout-theme-import-error">{themeImportError}</div>}
              <div className="ui-layout-theme-import-actions"><button type="button" onClick={()=>setThemeImportOpen(false)}>취소</button><button type="button" className="primary" disabled={themeImportBusy} onClick={importTheme}>{themeImportBusy?'통합 분석·저장 중...':'분석 후 Theme 저장'}</button></div>
            </div>}
            <label className="ui-layout-select-field"><span>사용자 메뉴 위치</span><select value={draft.user_menu_position||'header_right'} disabled={!draft.user_menu} onChange={(e: LegacyValue)=>patch({user_menu_position:e.target.value})}><option value="header_right">상단 우측</option><option value="sidebar_bottom">Sidebar 하단</option><option value="profile_page">Profile 페이지</option></select></label>
          </section>

          <section className="ui-layout-config-section runtime">
            <div className="ui-layout-config-section-head"><strong>실행 및 상태 유지</strong><small>다른 메뉴를 사용해도 실행과 작업 Context를 이어갑니다.</small></div>
            <div className="ui-layout-runtime-lock">
              <span aria-hidden="true">🔒</span>
              <div><strong>메뉴 이동 시 Agent 실행 유지</strong><small>UI lifecycle과 Agent Runtime을 분리하여 메뉴·탭 이동으로 실행을 중단하지 않습니다.</small></div>
              <em>항상 ON</em>
            </div>
            <div className="ui-layout-toggle-grid runtime">
              <label><input type="checkbox" checked={draft.restore_screen_state!==false} disabled={selectedId==='headless_agent'} onChange={(e: LegacyValue)=>patch({restore_screen_state:e.target.checked})}/>이전 화면 상태 복원</label>
              <label><input type="checkbox" checked={draft.restore_scroll_position!==false} disabled={selectedId==='headless_agent'} onChange={(e: LegacyValue)=>patch({restore_scroll_position:e.target.checked})}/>스크롤 위치 복원</label>
              <label><input type="checkbox" checked={Boolean(draft.restore_draft_input)} disabled={selectedId==='headless_agent'} onChange={(e: LegacyValue)=>patch({restore_draft_input:e.target.checked})}/>입력 중 내용 복원</label>
              <label><input type="checkbox" checked={draft.restore_selection_state!==false} disabled={selectedId==='headless_agent'} onChange={(e: LegacyValue)=>patch({restore_selection_state:e.target.checked})}/>선택/탭 상태 복원</label>
              <label><input type="checkbox" checked={draft.show_running_tasks!==false} onChange={(e: LegacyValue)=>patch({show_running_tasks:e.target.checked})}/>실행 중 작업 표시</label>
            </div>
            <label className="ui-layout-select-field"><span>실행 상태 위치</span><select value={draft.runtime_status_position||'top_statusbar'} disabled={draft.show_running_tasks===false} onChange={(e: LegacyValue)=>patch({runtime_status_position:e.target.value})}><option value="top_statusbar">상단 상태바</option><option value="sidebar">좌측 메뉴</option><option value="right_panel">우측 패널</option><option value="bottom_statusbar">하단 상태바</option><option value="floating_button">플로팅 버튼</option></select></label>
            <label className="ui-layout-select-field"><span>화면 유지 방식</span><select value={draft.screen_restore_mode||'auto'} disabled={selectedId==='headless_agent'} onChange={(e: LegacyValue)=>patch({screen_restore_mode:e.target.value})}><option value="auto">자동 (권장)</option><option value="keep_alive">화면 유지 (Keep Alive)</option><option value="state_rehydrate">상태 저장 후 재생성</option></select></label>
            <div className="ui-layout-runtime-note"><b>자동 복구</b><span>WebSocket/SSE 재연결 · 현재 run 상태 재조회 · 누락 이벤트 재동기화는 플랫폼 기본 정책으로 적용됩니다.</span></div>
          </section>

          <section className="ui-layout-config-section">
            <div className="ui-layout-config-section-head"><strong>알림</strong><small>백그라운드 실행 결과를 놓치지 않도록 표시합니다.</small></div>
            <div className="ui-layout-toggle-grid">
              <label><input type="checkbox" checked={draft.notify_agent_complete!==false} onChange={(e: LegacyValue)=>patch({notify_agent_complete:e.target.checked})}/>Agent 완료 알림</label>
              <label><input type="checkbox" checked={draft.notify_agent_failure!==false} onChange={(e: LegacyValue)=>patch({notify_agent_failure:e.target.checked})}/>Agent 실패 알림</label>
              <label className="wide"><input type="checkbox" checked={draft.run_item_navigate!==false} onChange={(e: LegacyValue)=>patch({run_item_navigate:e.target.checked})}/>실행 작업 클릭 시 해당 화면으로 이동</label>
            </div>
          </section>

          <div className="ui-layout-component-tags">{(draft.components||[]).map((item: LegacyValue)=><span key={item}>{item}</span>)}</div>
          <div className="ui-layout-config-actions"><button type="button" onClick={onClose}>취소</button><button type="button" className="primary" onClick={()=>onApply(normalizeUILayoutConfig(selected,{...draft,template_id:selectedId,selected_at:new Date().toISOString()}))}>이 레이아웃 사용</button></div>
        </aside>
      </div>

      {themePreviewOpen&&<div className="ui-layout-theme-preview-modal-backdrop" onMouseDown={()=>setThemePreviewOpen(false)}>
        <div className="ui-layout-theme-preview-modal" style={uiThemePreviewStyleVars({...draft,template_id:selectedId})} onMouseDown={(event: LegacyValue)=>event.stopPropagation()}>
          <div className="ui-layout-theme-preview-modal-head">
            <div><span>LAYOUT + THEME PREVIEW</span><strong>{draft.theme==='custom'?(draft.theme_name||'Custom Theme'):(draft.theme==='dark'?'Dark':draft.theme==='auto'?'Auto':'Light')} · {selected.name}</strong><small>미리보기 안에서 직접 마우스 오버·메뉴 클릭·하위 메뉴·사용자 메뉴·입력 Focus를 조작해 외부 Theme의 실제 상태 스타일을 검증합니다.</small></div>
            <button type="button" onClick={()=>setThemePreviewOpen(false)}>×</button>
          </div>
          <div className="ui-layout-theme-preview-modal-tools">
            {['desktop','tablet','mobile'].map((item: LegacyValue)=><button key={item} type="button" className={themePreviewViewport===item?'active':''} onClick={()=>setThemePreviewViewport(item)}>{item==='desktop'?'Desktop':item==='tablet'?'Tablet':'Mobile'}</button>)}
          </div>
          <div className="ui-layout-theme-preview-modal-body">
            <UILayoutThemePreview config={{...draft,template_id:selectedId}} viewport={themePreviewViewport}/>
          </div>
          <div className="ui-layout-theme-preview-modal-legend interactive">
            <span>🖱 메뉴 Hover</span><span>☰ 메뉴 클릭/Open</span><span>👤 사용자 메뉴 클릭</span>
            <small>아래 '외부 스타일 재현 근거'에서 URL CSS 확인 / 캡처 참고 / 추정 상태를 구분합니다.</small>
          </div>
        </div>
      </div>}

      {frontendThemeListOpen&&<div className="ui-layout-theme-target-modal-backdrop" onMouseDown={()=>setFrontendThemeListOpen(false)}>
        <div className="ui-layout-theme-target-modal" onMouseDown={(event: LegacyValue)=>event.stopPropagation()}>
          <div className="ui-layout-theme-target-modal-head">
            <div>
              <span>THEME ADAPTER REGISTRY</span>
              <strong>지원 Frontend / 스타일 목록</strong>
              <small>Theme Design Token을 각 Frontend와 UI Framework에 맞는 방식으로 변환합니다.</small>
            </div>
            <button type="button" onClick={()=>setFrontendThemeListOpen(false)}>×</button>
          </div>
          <div className="ui-layout-theme-target-modal-stats">
            <b>{frontendThemeTargets.length}</b>
            <span>등록된 Adapter</span>
            <small>목록에 없는 기술은 Generic Theme Adapter로 처리합니다.</small>
          </div>
          <div className="ui-layout-theme-target-list modal-list">
            {frontendThemeTargets.length===0
              ?<div className="ui-layout-theme-target-empty">Frontend 목록을 불러오는 중이거나 Backend 연결을 확인할 수 없습니다.</div>
              :Array.from(new Set(frontendThemeTargets.map((item: LegacyValue)=>item.group||'기타'))).map((group: LegacyValue)=><div key={group} className="ui-layout-theme-target-group"><strong>{group}</strong><div>{frontendThemeTargets.filter((item: LegacyValue)=>(item.group||'기타')===group).map((item: LegacyValue)=><span key={item.id} title={item.strategy||''}><b>{item.label}</b><em>{item.language}</em></span>)}</div></div>)}
            <small className="ui-layout-theme-target-footnote">목록에 없는 Frontend도 Generic Theme Adapter를 사용해 같은 색상·타이포그래피·Radius·Shadow·Spacing 의미를 유지합니다.</small>
          </div>
        </div>
      </div>}
    </div>
  </div>
}

const protectInterviewAssistantAnswer=(value: LegacyValue='')=>{
  const text=sanitizeInterviewDisplayText(value)
  if(!text) return text

  // Legacy v5.334~v5.336 drafts can contain an attachment body copied almost
  // verbatim by a local model. Some of those dumps were flattened into one
  // very long visual line, so do not rely only on line-start code markers.
  const lineCodeSignals=(text.match(/(?:^|\n)\s*(?:```|import\s+|from\s+\S+\s+import|def\s+|class\s+|SELECT\s+|CREATE\s+)/gim)||[]).length
  const inlineCodeSignals=(text.match(/\b(?:import|from|def|class|streamlit|langchain|psycopg|redis|pgvector|openai|pinecone|chromadb|faiss|select|create|insert|update|delete)\b/gi)||[]).length
  const hasLargeFence=/```(?:python|py|javascript|typescript|sql|json|bash|powershell)?/i.test(text)&&text.length>=1200
  const looksLikeFlattenedDump=text.length>=1800&&inlineCodeSignals>=12
  const looksLikeMultilineDump=text.length>=2200&&lineCodeSignals>=4

  if(hasLargeFence||looksLikeFlattenedDump||looksLikeMultilineDump){
    return '이전에 저장된 첨부 파일 원문/긴 코드 출력은 현재 인터뷰에서 제외했습니다. 참고 파일은 다시 선택하면 안전한 분석 Context로만 반영됩니다.\n\n현재 요구사항을 이어서 진행해 주세요.'
  }
  return text
}
const DEFAULT_WEB_BROWSER_ID='web-browser-fixed'




function redevelopmentResumeNodeForFailure(stage: LegacyValue='',status: LegacyValue=''){
  const raw=String(stage||'').trim().toLowerCase().replace(/[-/]/g,'_')
  const previous={
    requirement_analysis:'requirement_analysis',
    analyze_project:'requirement_analysis',
    capability_design:'analyze_project',
    tool_mcp_decision:'capability_design',
    agent_architecture:'tool_mcp_decision',
    database_design:'agent_architecture',
    target_workflow_design:'database_design',
    project_file_plan:'target_workflow_design',
    requirement_coverage_gate:'project_file_plan',
    settings_requirement_analysis:'requirement_coverage_gate',
    settings_schema_design:'settings_requirement_analysis',
    settings_ui_design:'settings_schema_design',
    checkpoint:'settings_ui_design',
    approval:'checkpoint',
    code_generation:'code_generation',
    settings_generator:'code_generation',
    settings_validation:'settings_generator',
    build_artifact_validation:'settings_validation',
    as_built_architecture:'build_artifact_validation',
    architecture_conformance:'as_built_architecture',
    environment_configuration:'architecture_conformance',
    test:'environment_configuration',
    debug:'test',
    package_completion:'test',
    review:'package_completion',
  }
  if((previous as LegacyRecord)[raw]) return (previous as LegacyRecord)[raw]
  const upper=String(status||'').toUpperCase()
  if(upper.includes('TEST')) return 'environment_configuration'
  if(upper.includes('ARCHITECTURE')) return 'as_built_architecture'
  if(upper.includes('SETTINGS')) return 'settings_generator'
  if(upper.includes('CODE_PLAN')||upper.includes('COVERAGE')) return 'project_file_plan'
  return 'settings_validation'
}



