    const menu=firestoreContextMenu
    if(!menu||!activeWorkspaceRoot||!sqlConnectionStatus?.connected||firestoreScriptBusy) return
    const normalized=String(action||'').toLowerCase()
    setFirestoreContextMenu(null)
